    self.stack_updates += 1

    self.app._refresh_notifications()
    size = self.app.size

    self._update_auto_focus()

    if self.is_attached:

        if event.refresh_styles:
            self.update_node_styles(animate=False)
        if self._size != size:
            self._refresh_layout(size)
        self.refresh()

